inline constexpr std::size_t Count() {
    return kItems.size();
}

inline const ItemDataEntry* FindById(int id) {
    std::size_t lo = 0;
    std::size_t hi = kItems.size();
    while (lo < hi) {
        const std::size_t mid = lo + ((hi - lo) / 2);
        if (kItems[mid].Id < id) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo < kItems.size() && kItems[lo].Id == id ? &kItems[lo] : nullptr;
}

